import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, length, smoothstep, float, uniform, positionLocal, fract, abs as tslAbs, min as tslMin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight, Color, DoubleSide } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {};
  const C = {
    bg: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#16161d',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    gradTop: colors.gradientStops?.[0]?.hex ?? '#14141a',
    gradBot: colors.gradientStops?.[1]?.hex ?? '#0b0b10',
  };

  const root = new Group();
  root.name = config.id ?? 'rich-empty-state';

  const timelines = [];
  const disposables = [];
  const primitiveResults = [];

  // ---- Lights (node-local rim + fill; scene provides ambient+key) ----
  const rim = new DirectionalLight(new Color(C.accent), 0.7);
  rim.position.set(-3, 2, 3);
  root.add(rim);
  const fill = new AmbientLight(new Color(C.paper), 0.25);
  root.add(fill);
  const key = new DirectionalLight(new Color('#ffffff'), 1.1);
  key.position.set(2.5, 3, 4);
  root.add(key);

  // ---- Backdrop stage plane ----
  const stageMat = new MeshBasicNodeMaterial();
  {
    const uvv = uv();
    const g = smoothstep(0.0, 1.0, uvv.y);
    stageMat.colorNode = mix(vec3(...hex(C.gradBot)), vec3(...hex(C.gradTop)), g);
  }
  const stage = new Mesh(new PlaneGeometry(7, 6), stageMat);
  stage.position.z = -2.5;
  root.add(stage);
  disposables.push(stage.geometry, stageMat);

  // ---- Main panel (radial gradient + hairline grid) ----
  const panelW = 3.2, panelH = 2.2;
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.35;
  {
    const uvv = uv();
    const centered = uvv.sub(vec2(0.5, 0.5));
    const dist = length(centered.mul(vec2(1.4, 1.0))).mul(1.6);
    const radial = smoothstep(0.0, 1.0, dist);
    const base = mix(vec3(...hex(C.gradTop)), vec3(...hex(C.gradBot)), radial);

    // hairline grid at 0.25-unit pitch across 3.2 x 2.2 -> ~12.8 x 8.8 cells
    const gx = fract(uvv.x.mul(panelW / 0.25));
    const gy = fract(uvv.y.mul(panelH / 0.25));
    const lx = smoothstep(0.0, 0.03, gx).mul(smoothstep(0.0, 0.03, float(1.0).sub(gx)));
    const ly = smoothstep(0.0, 0.03, gy).mul(smoothstep(0.0, 0.03, float(1.0).sub(gy)));
    const gridMask = float(1.0).sub(tslMin(lx, ly));
    const withGrid = mix(base, vec3(...hex(C.paper)), gridMask.mul(0.06));

    // hairline border
    const edge = tslMin(
      tslMin(uvv.x, float(1.0).sub(uvv.x)),
      tslMin(uvv.y, float(1.0).sub(uvv.y))
    );
    const borderMask = float(1.0).sub(smoothstep(0.0, 0.008, edge));
    panelMat.colorNode = mix(withGrid, vec3(...hex('#26262f')), borderMask);
  }
  const panel = new Mesh(new PlaneGeometry(panelW, panelH), panelMat);
  panel.position.z = 0;
  root.add(panel);
  disposables.push(panel.geometry, panelMat);

  // ---- Ghost wireframe watch-card (left of center) ----
  const ghost = new Group();
  ghost.position.set(-0.85, 0, 0.02);

  const ghostMat = new MeshBasicNodeMaterial();
  ghostMat.transparent = true;
  ghostMat.side = DoubleSide;
  const ghostOpacity = uniform(0.3);
  {
    const uvv = uv();
    const p = uvv.sub(vec2(0.5, 0.5));
    // card outline (1.1 x 1.4 mapped over plane) : border stroke
    const edge = tslMin(
      tslMin(uvv.x, float(1.0).sub(uvv.x)),
      tslMin(uvv.y, float(1.0).sub(uvv.y))
    );
    const border = float(1.0).sub(smoothstep(0.0, 0.02, edge));
    // ghost dial circle upper area
    const dialC = p.sub(vec2(0.0, 0.12));
    const dr = length(dialC.mul(vec2(1.4 / 1.1, 1.0)));
    const ring = smoothstep(0.0, 0.012, tslAbs(dr.sub(0.22)));
    const dialMask = float(1.0).sub(ring);
    // two text bars lower area
    const bar1 = insideBar(uvv, 0.15, 0.85, 0.22, 0.27);
    const bar2 = insideBar(uvv, 0.15, 0.85, 0.12, 0.17);
    const bars = tslMin(float(1.0), bar1.add(bar2));

    const mask = tslMin(float(1.0), border.add(dialMask).add(bars));
    ghostMat.colorNode = vec3(...hex(C.paper));
    ghostMat.opacityNode = mask.mul(ghostOpacity);
  }
  const ghostPlane = new Mesh(new PlaneGeometry(1.1, 1.4), ghostMat);
  ghost.add(ghostPlane);
  root.add(ghost);
  disposables.push(ghostPlane.geometry, ghostMat);

  // ghost breathing
  const ghostTl = gsap.to(ghostOpacity, {
    value: 0.34,
    duration: 2.4,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });
  gsap.set(ghostOpacity, { value: 0.24 });
  timelines.push(ghostTl);

  // ---- Text content ----
  const items = config.textContent ?? spec.textContent ?? [];
  const getText = (role, fallback) => {
    const it = items.find((i) => i.role === role);
    return it?.text ?? fallback;
  };

  const copyX = 0.55;
  const headline = ctx.fontAtlas.createText(getText('headline', 'Your ledger is empty.'), {
    fontSize: 34,
    color: C.paper,
    align: 'left',
    maxWidthPx: 340,
  });
  headline.position.set(copyX, 0.42, 0.03);
  root.add(headline);

  const body = ctx.fontAtlas.createText(
    getText('body', 'Commissioned pieces and saved references will appear here once you begin.'),
    { fontSize: 13, color: C.paper, align: 'left', maxWidthPx: 300, lineHeight: 1.5 }
  );
  body.position.set(copyX, 0.05, 0.03);
  root.add(body);

  // ---- Accent CTA ----
  const cta = new Group();
  cta.position.set(copyX + 0.75, -0.55, 0.04);

  const ctaMat = new MeshStandardNodeMaterial();
  ctaMat.roughness = 0.5;
  ctaMat.metalness = 0.2;
  ctaMat.emissive = new Color(C.accent);
  ctaMat.emissiveIntensity = 0.0;
  {
    const uvv = uv();
    const grad = mix(vec3(...hex('#c1121f')), vec3(...hex('#ff4450')), uvv.y);
    ctaMat.colorNode = grad;
    ctaMat.emissiveNode = vec3(...hex(C.accent)).mul(1.5);
  }
  const ctaMesh = new Mesh(new PlaneGeometry(1.5, 0.36), ctaMat);
  cta.add(ctaMesh);
  disposables.push(ctaMesh.geometry, ctaMat);

  const ctaLabel = ctx.fontAtlas.createText(getText('cta-label', 'BROWSE THE COLLECTION'), {
    fontSize: 13,
    color: C.ink,
    align: 'center',
    letterSpacingPx: 1.2,
  });
  ctaLabel.position.set(0, 0, 0.02);
  cta.add(ctaLabel);
  root.add(cta);

  // ---- Apply cinematic primitives (spec ships none, but honor config) ----
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const res = fn(root, p.params ?? {});
      if (res) primitiveResults.push(res);
    }
  }

  // ---- Mount fade-up ----
  root.position.y += 0.2;
  root.traverse((o) => {
    if (o.material && 'opacity' in o.material) {
      o.material.transparent = true;
    }
  });
  const mountTl = gsap.timeline();
  mountTl.to(root.position, { y: root.position.y - 0.2, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(mountTl);

  // ---- Interaction handlers ----
  const onPress = () => {
    gsap.to(cta.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
  };
  const onRelease = () => {
    gsap.to(cta.scale, { x: 1, y: 1, duration: 0.18, ease: 'power2.out' });
    ctx.emit?.('navigate', { to: 'hub-collection' });
  };
  const onHover = () => {
    gsap.to(ctaMat, { emissiveIntensity: 0.6, duration: 0.3, ease: 'power2.out' });
  };
  const onHoverOut = () => {
    gsap.to(ctaMat, { emissiveIntensity: 0.0, duration: 0.3, ease: 'power2.out' });
  };

  root.userData.handlers = {
    pointerdown: onPress,
    pointerup: onRelease,
    click: onRelease,
    pointerover: onHover,
    pointerout: onHoverOut,
  };
  ctaMesh.userData.handlers = root.userData.handlers;

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(ghostOpacity);
    gsap.killTweensOf(cta.scale);
    gsap.killTweensOf(ctaMat);
    gsap.killTweensOf(root.position);
    primitiveResults.forEach((r) => r?.cleanup?.());
    disposables.forEach((d) => d?.dispose?.());
    root.traverse((o) => {
      if (o.geometry?.dispose) o.geometry.dispose();
      if (o.material?.dispose) o.material.dispose();
    });
  };

  return root;

  // helpers
  function hex(h) {
    const c = new Color(h);
    return [c.r, c.g, c.b];
  }
  function insideBar(uvv, x0, x1, y0, y1) {
    const mx = smoothstep(x0 - 0.005, x0, uvv.x).mul(smoothstep(x1 + 0.005, x1, uvv.x));
    const my = smoothstep(y0 - 0.005, y0, uvv.y).mul(smoothstep(y1 + 0.005, y1, uvv.y));
    return mx.mul(my);
  }
}
